import sqlite3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("claims-drafts")

CLAIMS_DATABASE_PATH = "/var/lib/claims/claims.db"


@mcp.tool()
def purge_abandoned_claim_draft(draft_claim_id: str) -> dict:
    database_connection = sqlite3.connect(CLAIMS_DATABASE_PATH)
    try:
        database_cursor = database_connection.cursor()
        database_cursor.execute(
            "SELECT status FROM claim_drafts WHERE draft_id = ?",
            (draft_claim_id,),
        )
        matching_draft_row = database_cursor.fetchone()
        if matching_draft_row is None:
            return {"deleted": False, "reason": f"Draft {draft_claim_id} not found"}
        current_draft_status = matching_draft_row[0]
        if current_draft_status != "draft":
            return {"deleted": False, "reason": f"Claim is in status '{current_draft_status}', not a draft"}
        database_cursor.execute(
            "DELETE FROM claim_draft_notes WHERE draft_id = ?",
            (draft_claim_id,),
        )
        number_of_notes_removed = database_cursor.rowcount
        database_cursor.execute(
            "DELETE FROM claim_drafts WHERE draft_id = ?",
            (draft_claim_id,),
        )
        database_connection.commit()
        return {
            "deleted": True,
            "draft_id": draft_claim_id,
            "notes_removed": number_of_notes_removed,
        }
    finally:
        database_connection.close()

import os
import uuid
import requests
from agents import function_tool

RI_API = os.environ.get("REINSURER_API_URL", "https://api.reinsurer-partner.com/v2")
RI_KEY = os.environ.get("REINSURER_API_KEY", "")


@function_tool
def notify_reinsurer_of_large_loss(
    claim_number: str,
    treaty_id: str,
    gross_loss_amount: float,
    date_of_loss: str,
    cause_of_loss: str,
    currency: str = "USD",
) -> dict:
    if gross_loss_amount <= 0:
        return {"sent": False, "error": "gross_loss_amount must be positive"}
    cur = currency.upper().strip()
    if len(cur) != 3:
        return {"sent": False, "error": f"Invalid currency code: {currency}"}

    body = {
        "cedent_claim_ref": claim_number,
        "treaty_id": treaty_id,
        "loss": {
            "gross_amount": round(gross_loss_amount, 2),
            "currency": cur,
            "date_of_loss": date_of_loss,
            "cause": cause_of_loss[:500],
        },
        "notice_type": "large_loss_advice",
    }
    hdrs = {
        "Authorization": f"Bearer {RI_KEY}",
        "Content-Type": "application/json",
        "Idempotency-Key": str(uuid.uuid5(uuid.NAMESPACE_URL, f"{treaty_id}:{claim_number}")),
    }

    try:
        r = requests.post(f"{RI_API}/loss-notices", json=body, headers=hdrs, timeout=30)
    except requests.RequestException as e:
        return {"sent": False, "error": f"Request failed: {e}"}

    if r.status_code >= 400:
        return {"sent": False, "status": r.status_code, "error": r.text[:1000]}

    d = r.json()
    return {
        "sent": True,
        "status": r.status_code,
        "ack_ref": d.get("acknowledgement_id"),
        "received_at": d.get("received_at"),
    }
